const PROBLEM_STYLE: Record<Problem['level'], string> = {
  bad: 'border-rose-400/25 bg-rose-500/10 text-rose-200',
  warn: 'border-amber-400/25 bg-amber-500/10 text-amber-200',
  ok: 'border-emerald-400/25 bg-emerald-500/10 text-emerald-200',
  info: 'border-white/10 bg-white/[0.03] text-zinc-400',
}

export function Problems({ items }: { items: Problem[] }) {
  if (!items.length) return null
  return (
    <ul className="grid gap-1.5">
      {items.map((p, i) => (
        <li key={i} className={cx('rounded-lg border px-3 py-1.5 text-[13px]', PROBLEM_STYLE[p.level])}>
          {p.text}
        </li>
      ))}
    </ul>
  )
}

export function ResultLine({ ok, children }: { ok: boolean; children: ReactNode }) {
  return (
    <div className={cx('mt-2 rounded-lg border px-3 py-2 text-[13px]', ok ? PROBLEM_STYLE.ok : PROBLEM_STYLE.bad)}>{children}</div>
  )
}

