// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Now i want this change. the LL tab should be split into two, rather it should have 2 modes:\n- simulation\n- viewer"
// Changes: Segmented pill control (radio group) – LL mode switch and simulation speed.
export function Segmented<V extends string | number>({
  label,
  value,
  options,
  onChange,
  size = 'md',
}: {
  label: string
  value: V
  options: { value: V; label: ReactNode }[]
  onChange: (value: V) => void
  size?: 'sm' | 'md'
}) {
  return (
    <div role="radiogroup" aria-label={label} className="inline-flex rounded-full border border-white/10 bg-white/5 p-0.5">
      {options.map((o) => (
        <button
          key={String(o.value)}
          type="button"
          role="radio"
          aria-checked={value === o.value}
          onClick={() => onChange(o.value)}
          className={cx(
            'rounded-full tabular-nums transition focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-indigo-400',
            size === 'sm' ? 'px-2.5 py-1 text-xs' : 'px-4 py-1.5 text-sm',
            value === o.value ? 'bg-indigo-500/30 text-indigo-100' : 'text-zinc-400 hover:bg-white/10 hover:text-zinc-200',
          )}
        >
          {o.label}
        </button>
      ))}
    </div>
  )
}

